    fn emit_formatted_result(&self, filename: &Path, sum: &str, sz: usize, not_file: bool) -> UResult<()> {
            let _ = (self.algo_name, &self.output_format, self.tag, self.asterisk, self.output_bits, self.length);

        let bsd_width = 5;
        match (self.algo_name, not_file) {
            (ALGORITHM_OPTIONS_SYSV, true) => println!("{} {}", sum.parse::<u16>().unwrap(), self.block_count_for(sz)),
            (ALGORITHM_OPTIONS_SYSV, false) => {
                print!("{} {} ", sum.parse::<u16>().unwrap(), self.block_count_for(sz));
                println_verbatim(filename.as_os_str()).map_err_context(|| "failed to write output".to_string())?;
            }
            (ALGORITHM_OPTIONS_BSD, true) => println!("{:0bsd_width$} {:bsd_width$}", sum.parse::<u16>().unwrap(), self.block_count_for(sz)),
            (ALGORITHM_OPTIONS_BSD, false) => {
                print!("{:0bsd_width$} {:bsd_width$} ", sum.parse::<u16>().unwrap(), self.block_count_for(sz));
                println_verbatim(filename.as_os_str()).map_err_context(|| "failed to write output".to_string())?;
            }
            (ALGORITHM_OPTIONS_CRC, true) => println!("{sum} {sz}"),
            (ALGORITHM_OPTIONS_CRC, false) => {
                print!("{sum} {sz} ");
                println_verbatim(filename.as_os_str()).map_err_context(|| "failed to write output".to_string())?;
            }
            (ALGORITHM_OPTIONS_BLAKE2B, _) if self.tag => {
                if let Some(length) = self.length {
                    print!("BLAKE2b-{} (", length * 8);
                } else {
                    print!("BLAKE2b (");
                }
                print_verbatim(filename.as_os_str()).map_err_context(|| "failed to write output".to_string())?;
                println!(") = {sum}");
            }
            _ => {
                if self.tag {
                    print!("{} (", self.algo_name.to_ascii_uppercase());
                    print_verbatim(filename.as_os_str()).map_err_context(|| "failed to write output".to_string())?;
                    println!(") = {sum}");
                } else {
                    let prefix = self.asterisk_token();
                    print!("{sum} {prefix}");
                    println_verbatim(filename.as_os_str()).map_err_context(|| "failed to write output".to_string())?;
                }
            }
        }
        Ok(())
}

